<script setup lang="ts">
import {ref,computed} from 'vue'
import {IconX,IconChevronRight} from '@tabler/icons-vue'
import type {components} from '../../shared/api'
import {attitudeOptions,type Catalogue} from './profile-fields'
type Choice=components['schemas']['PracticeChoice']
const props=defineProps<{modelValue:Choice[];catalogue:Catalogue;ru:boolean}>()
const emit=defineEmits<{'update:modelValue':[Choice[]]}>()
const search=ref(''),category=ref(''),selected=ref('')
const filtered=computed(()=>(props.catalogue.practices??[]).filter(p=>(!category.value||p.category_uid===category.value)&&p.name.toLocaleLowerCase().includes(search.value.toLocaleLowerCase())))
const current=computed(()=>props.modelValue.find(p=>p.practice_uid===selected.value)??{practice_uid:selected.value,attitude:'not_specified',experience:'not_specified',participation:'not_specified',conditions:''})
const chosen=computed(()=>props.catalogue.practices?.find(p=>p.uid===selected.value))
function update(key:string,value:string){const row={...current.value,[key]:value} as Choice;emit('update:modelValue',[...props.modelValue.filter(p=>p.practice_uid!==row.practice_uid),row])}
function label(uid:string){const value=props.modelValue.find(p=>p.practice_uid===uid)?.attitude??'not_specified';return attitudeOptions.find(o=>o[0]===value)?.[props.ru?1:2]}
</script>
<template><div class="profile-practice-browser"><div class="profile-practice-list"><label>{{ru?'Поиск практики':'Find a practice'}}<input v-model="search" type="search" :placeholder="ru?'Название практики…':'Practice name…'"></label><label>{{ru?'Категория':'Category'}}<select v-model="category"><option value="">{{ru?'Все категории':'All categories'}}</option><option v-for="item in catalogue['practice-categories']" :key="item.uid" :value="item.uid">{{item.name}}</option></select></label><div class="profile-practice-rows"><button v-for="item in filtered" :key="item.uid" type="button" :class="{selected:selected===item.uid}" @click="selected=item.uid"><img v-if="item.thumbnail" :src="item.thumbnail" alt="" loading="lazy"><span><strong>{{item.name}}</strong><small>{{label(item.uid)}}</small></span><IconChevronRight :size="18"/></button><p v-if="!filtered.length" class="muted">{{ru?'Ничего не найдено':'No results'}}</p></div></div><section v-if="chosen" class="profile-practice-detail"><header><h3>{{chosen.name}}</h3><button type="button" class="quiet-button" :aria-label="ru?'Закрыть практику':'Close practice'" @click="selected=''"><IconX :size="18"/></button></header><img v-if="chosen.thumbnail" :src="chosen.thumbnail" alt="" class="profile-practice-art"><label>{{ru?'Моё отношение':'My preference'}}<select :value="current.attitude" @change="update('attitude',($event.target as HTMLSelectElement).value)"><option v-for="option in attitudeOptions" :key="option[0]" :value="option[0]">{{option[ru?1:2]}}</option></select></label><label>{{ru?'Мой опыт':'My experience'}}<select :value="current.experience" @change="update('experience',($event.target as HTMLSelectElement).value)"><option value="not_specified">{{ru?'Не указан':'Not specified'}}</option><option value="none">{{ru?'Без опыта':'No experience'}}</option><option value="tried">{{ru?'Пробовал(а)':'Tried'}}</option><option value="experienced">{{ru?'Есть опыт':'Experienced'}}</option></select></label><label>{{ru?'Моё участие':'My participation'}}<select :value="current.participation" @change="update('participation',($event.target as HTMLSelectElement).value)"><option value="not_specified">{{ru?'Не указано':'Not specified'}}</option><option value="give">{{ru?'Делать':'Give'}}</option><option value="receive">{{ru?'Получать':'Receive'}}</option><option value="both">{{ru?'Оба':'Both'}}</option></select></label><label>{{ru?'Условия и комментарий':'Conditions & notes'}}<textarea :value="current.conditions" rows="3" maxlength="2000" @input="update('conditions',($event.target as HTMLTextAreaElement).value)"/></label><button type="button" class="quiet-button" @click="emit('update:modelValue',modelValue.filter(p=>p.practice_uid!==selected));selected=''">{{ru?'Убрать из профиля':'Remove from profile'}}</button></section><p v-else class="profile-detail-hint muted">{{ru?'Выберите практику, чтобы отдельно указать отношение, опыт и участие.':'Select a practice to set preference, experience and participation independently.'}}</p></div></template>
